import { z } from 'zod';
import { classSchema, combatFieldSchema, factionSchema } from './schemas';

/** R4 Potential (kb/potential.md), generated by scripts/import-potential.mjs. */
const slotSchema = z.enum(['normal', 'basic', 'ult']);

const effectSchema = z.discriminatedUnion('kind', [
  z.object({
    kind: z.literal('stat'),
    field: combatFieldSchema,
    mult: z.boolean().optional(),
    negate: z.boolean().optional(),
    extra: z.object({ field: combatFieldSchema, add: z.number() }).optional(),
  }),
  z.object({ kind: z.literal('factionAllies'), field: combatFieldSchema, mult: z.boolean().optional(), cap: z.number().int().positive() }),
  z.object({ kind: z.literal('classAlly'), allyClass: classSchema, field: combatFieldSchema, mult: z.boolean().optional() }),
  z.object({ kind: z.literal('classAllyDmg'), allyClass: classSchema, role: z.enum(['attack', 'defend']), vs: classSchema }),
  z.object({ kind: z.literal('alive'), atLeast: z.number().int().optional(), below: z.number().int().optional(), field: combatFieldSchema }),
  z.object({
    kind: z.literal('event'),
    on: z.enum(['afterAttack', 'afterUlt', 'afterNonUlt', 'afterNormal', 'afterBasic', 'onHit', 'battleStart']),
    hitBy: slotSchema.optional(),
    target: z.enum(['self', 'event', 'allies']),
    act: z.enum(['buff', 'heal', 'damage']),
    field: combatFieldSchema.optional(),
    negate: z.boolean().optional(),
    maxStacks: z.number().int().positive().optional(),
    turns: z.number().int().positive().optional(),
    bigRounds: z.number().int().positive().optional(),
    perTurn: z.number().int().positive().optional(),
  }),
]);

const fodderSchema = z.object({
  own: z.boolean(),
  star: z.number().int().positive(),
  count: z.number().int().positive(),
  faction: factionSchema.optional(),
});

export const potentialSchema = z.object({
  unlockStars: z.array(z.number().int().positive()).length(9),
  costs: z.array(z.array(z.number().int().positive()).length(6)).length(9),
  maxLevel: z.number().int().positive(),
  resetGems: z.number().int().nonnegative(),
  options: z.array(
    z.object({
      id: z.number().int(),
      name: z.string().min(1),
      tier: z.number().int().min(1).max(9),
      values: z.array(z.number()).length(6),
      effect: effectSchema,
      text: z.string().min(1),
    }),
  ),
  species: z.record(
    z.string(),
    z.object({
      tiers: z.array(z.array(z.number().int()).length(3)).length(9),
      fodder: z.array(z.array(fodderSchema).min(1)).length(9),
      core: z.boolean(),
    }),
  ),
});

export type PotentialJson = z.infer<typeof potentialSchema>;
